/* bat_soh_model.h - capacity-fraction regressor from partial-cycle features (generated by gen_p3.py).
 * Model: ridge regression (picked over GBDT depth-2 x40 and MLP-8 by forward-chaining CV on Raw cycles <= 450).
 * Held-out Raw cycles >= 461: MAPE 1.45 % vs DCIR-trend baseline 6.42 %;
 * the full-ends coulomb count (0.08 %) is better whenever a full empty-to-full charge exists - use it then.
 * Not validated cross-cell: discharge-only transfer to NASA failed (see REPORT). rel_* = value / the cell's own
 * median over its first 10 usable cycles (learned on the board). Cost: 8 MAC + 8 sub/mul, params 100 B.
 * Features, in order: rel_dq_chg_win, ica_chg_v, rel_ica_chg_h, cv_dur_h, rel_cv_tau_h, rel_dcir, T_avg, rel_ekf_ratio
 *   rel_dq_chg_win : Ah between 3.9 V and 4.1 V during CC charge / Q_nom, relative
 *   ica_chg_v      : voltage of the dQ/dV peak on CC charge (3.6 - 4.15 V, 10 mV grid, 5-point smoothing)
 *   rel_ica_chg_h  : height of that peak, relative
 *   cv_dur_h       : CV phase duration, hours
 *   rel_cv_tau_h   : CV current decay time constant (log-linear fit), relative
 *   rel_dcir       : DCIR at a rest -> load step (120 s), OCV-drop corrected, relative
 *   T_avg          : mean cell temperature over the cycle, deg C
 *   rel_ekf_ratio  : Ah / (1 - z_EKF) at z_EKF = 0.3 with nominal capacity, relative
 */
#ifndef BAT_SOH_MODEL_H
#define BAT_SOH_MODEL_H
#define BAT_SOH_NF 8
static const float BAT_SOH_MU[BAT_SOH_NF] = { 0.964582741f, 3.70756269f, 0.85490185f, 0.465126365f, 1.17473757f, 1.02548969f, 29.3121681f, 0.994401872f };
static const float BAT_SOH_ISD[BAT_SOH_NF] = { 85.745285f, 94.9518204f, 18.2940998f, 197.92244f, 4.8026123f, 7.00498056f, 2.00015903f, 45.2690849f };
static const float BAT_SOH_W[BAT_SOH_NF] = { 0.00463752355f, -0.00851130299f, 0.0254720282f, -0.000494462322f, -0.00467051566f, 0.0113337161f, 0.0014529787f, 0.00566657819f };
#define BAT_SOH_B 0.864745498f
static inline float bat_soh_predict(const float *x)
{
    float y = BAT_SOH_B;
    for (int j = 0; j < BAT_SOH_NF; j++) y += BAT_SOH_W[j] * (x[j] - BAT_SOH_MU[j]) * BAT_SOH_ISD[j];
    return y < 0.3f ? 0.3f : (y > 1.2f ? 1.2f : y);
}
#endif
